/**
 * Exact-output checks for both N-Triples writer constructors. The expected strings do not use serialization helpers.
 */
class NTriplesWriterOutputTest {

	private static final ValueFactory VF = SimpleValueFactory.getInstance();

	private static final IRI SUBJECT = VF.createIRI("urn:s");

	private static final IRI PREDICATE = VF.createIRI("urn:p");

	@Test
	void asciiTermsIgnoreContextsAndNamespaces() throws IOException {
		assertOutput("<urn:s> <urn:p> <urn:o> .\n"
				+ "<urn:s> <urn:p> \"plain\" .\n"
				+ "<urn:s> <urn:p> \"colour\"@en-GB .\n"
				+ "<urn:s> <urn:p> \"42\"^^<http://www.w3.org/2001/XMLSchema#integer> .\n"
				+ "_:genid311node5fe9 <urn:p> _:b2ec .\n", writer -> {
					writer.startRDF();
					writer.handleNamespace("example", "urn:");
					writer.handleStatement(statement(VF.createIRI("urn:o")));
					writer.handleStatement(VF.createStatement(SUBJECT, PREDICATE, VF.createLiteral("plain"),
							VF.createIRI("urn:ignored")));
					writer.handleStatement(statement(VF.createLiteral("colour", "en-GB")));
					writer.handleStatement(statement(VF.createLiteral("42", XSD.INTEGER)));
					writer.handleStatement(VF.createStatement(VF.createBNode("1node_é"), PREDICATE,
							VF.createBNode("b.c"), VF.createBNode("ignored")));
					writer.endRDF();
				});
	}

	@Test
	void literalEscapesRemainExact() throws IOException {
		assertStatements("<urn:s> <urn:p> \"\\t\\n\\r\\b\\f\\\"\\\\\\u0000\\u0007\\u000B\\u000E"
				+ "\\u001F\\u007F\" .\n", true,
				statement(VF.createLiteral("\t\n\r\b\f\"\\\u0000\u0007\u000b\u000e\u001f\u007f")));
	}

	@Test
	void unicodeIrisAndDatatypeIrisRetainTheirEscapingRules() throws IOException {
		Statement unicode = VF.createStatement(VF.createIRI("urn:s:é😀"), VF.createIRI("urn:p:Ω"),
				VF.createLiteral("café Ελληνικά 日本語 😀"));
		Statement datatype = statement(VF.createLiteral("é😀", VF.createIRI("urn:type:é😀")));
		String datatypeLine = "<urn:s> <urn:p> \"é😀\"^^<urn:type:\\u00E9\\U0001F600> .\n";
		assertStatements("<urn:s:\\u00E9\\U0001F600> <urn:p:\\u03A9> \"café Ελληνικά 日本語 😀\" .\n"
				+ datatypeLine, true, unicode, datatype);
		assertStatements("<urn:s:é😀> <urn:p:Ω> \"café Ελληνικά 日本語 😀\" .\n" + datatypeLine,
				false, unicode, datatype);
	}

	@Test
	void largeLiteralAndSupplementaryIriCrossBufferBoundaries() throws IOException {
		String iri = "http://example.org/resource?value=" + new String(Character.toChars(0x100000));
		String label = "a".repeat(1023) + "😀" + "é".repeat(4096) + "b".repeat(8191);
		Statement value = VF.createStatement(VF.createIRI(iri), PREDICATE, VF.createLiteral(label + "\n\"\\"));
		String tail = " <urn:p> \"" + label + "\\n\\\"\\\\\" .\n";
		assertStatements("<http://example.org/resource?value=\\U00100000>" + tail, true, value);
		assertStatements("<" + iri + ">" + tail, false, value);
	}

	@Test
	void nestedDirectionalTermsAnnounceVersionAtTheFirstAffectedStatement() throws IOException {
		TripleTerm inner = VF.createTripleTerm(VF.createBNode("inner.1"), PREDICATE,
				VF.createLiteral("مرحبا 😀", "ar", BaseDirection.RTL));
		TripleTerm outer = VF.createTripleTerm(SUBJECT, PREDICATE, inner);
		assertOutput("<urn:s> <urn:p> \"before\" .\n"
				+ "# between statements\n"
				+ "VERSION \"1.2\"\n"
				+ "<urn:s> <urn:p> <<( <urn:s> <urn:p> <<( _:inner2e1 <urn:p> \"مرحبا 😀\"@ar--rtl )>> )>> .\n"
				+ "<urn:s> <urn:p> \"after\"@en--ltr .\n", writer -> {
					writer.startRDF();
					writer.handleStatement(statement(VF.createLiteral("before")));
					writer.handleComment("between statements");
					writer.handleStatement(statement(outer));
					writer.handleStatement(statement(VF.createLiteral("after", "en", BaseDirection.LTR)));
					writer.endRDF();
				});
	}

	@Test
	void liveDatatypeSettingAndCapturedUnicodeSettingArePreserved() throws IOException {
		assertOutput("<urn:s> <urn:p> \"first\" .\n"
				+ "<urn:s> <urn:p> \"second\"^^<http://www.w3.org/2001/XMLSchema#string> .\n"
				+ "<urn:s> <urn:p> <urn:object:\\u00E9> .\n"
				+ "<urn:s> <urn:p> \"third\" .\n", writer -> {
					writer.startRDF();
					writer.handleStatement(statement(VF.createLiteral("first")));
					writer.getWriterConfig().set(BasicWriterSettings.XSD_STRING_TO_PLAIN_LITERAL, false);
					writer.handleStatement(statement(VF.createLiteral("second")));
					writer.getWriterConfig().set(NTriplesWriterSettings.ESCAPE_UNICODE, false);
					writer.handleStatement(statement(VF.createIRI("urn:object:é")));
					writer.getWriterConfig().set(BasicWriterSettings.XSD_STRING_TO_PLAIN_LITERAL, true);
					writer.handleStatement(statement(VF.createLiteral("third")));
					writer.endRDF();
				});
	}

	@Test
	void protectedValueOverridesApplyToSubjectAndObjectButNotPredicates() {
		ByteArrayOutputStream bytes = new ByteArrayOutputStream();
		StringWriter characters = new StringWriter();
		for (NTriplesWriter writer : new NTriplesWriter[] { new ReplacingWriter(bytes),
				new ReplacingWriter(characters) }) {
			configure(writer);
			writer.startRDF();
			writer.handleStatement(VF.createStatement(SUBJECT, SUBJECT,
					VF.createTripleTerm(SUBJECT, SUBJECT, SUBJECT)));
			writer.endRDF();
		}
		String expected = "VERSION \"1.2\"\n"
				+ "<urn:replacement> <urn:s> <<( <urn:replacement> <urn:s> <urn:replacement> )>> .\n";
		assertArrayEquals(expected.getBytes(StandardCharsets.UTF_8), bytes.toByteArray());
		assertEquals(expected, characters.toString());
	}

	@Test
	void exposedWriterInterleavesWithStatementsAndFlushesWithoutClosing() throws IOException {
		assertOutput("# before\n<urn:s> <urn:p> \"é😀\" .\n# after\n", writer -> {
			writer.startRDF();
			writer.getWriter().write("# before\n");
			writer.handleStatement(statement(VF.createLiteral("é😀")));
			writer.getWriter().write("# after\n");
			writer.getWriter().flush();
			writer.endRDF();
		});
	}

	private static Statement statement(Value value) {
		return VF.createStatement(SUBJECT, PREDICATE, value);
	}

	private static void configure(NTriplesWriter writer) {
		writer.getWriterConfig()
				.set(BasicWriterSettings.RDF_OUTPUT_VERSION, VersionLabel.RDF_1_2_FULL)
				.set(BasicWriterSettings.CONVERT_RDF_12_REIFICATION, false)
				.set(BasicWriterSettings.ANNOUNCE_RDF12_VERSION, true)
				.set(BasicWriterSettings.XSD_STRING_TO_PLAIN_LITERAL, true)
				.set(NTriplesWriterSettings.ESCAPE_UNICODE, true);
	}

	private static void assertStatements(String expected, boolean escapeUnicode, Statement... statements)
			throws IOException {
		assertOutput(expected, writer -> {
			writer.getWriterConfig().set(NTriplesWriterSettings.ESCAPE_UNICODE, escapeUnicode);
			writer.startRDF();
			for (Statement statement : statements) {
				writer.handleStatement(statement);
			}
			writer.endRDF();
		});
	}

	private static void assertOutput(String expected, WriterAction action) throws IOException {
		RecordingOutputStream bytes = new RecordingOutputStream();
		NTriplesWriter streamWriter = new NTriplesWriter(bytes);
		configure(streamWriter);
		action.write(streamWriter);
		assertArrayEquals(expected.getBytes(StandardCharsets.UTF_8), bytes.toByteArray(), "OutputStream output");
		assertTrue(bytes.flushes > 0);
		assertFalse(bytes.closed, "endRDF must leave the caller's stream open");

		RecordingWriter characters = new RecordingWriter();
		NTriplesWriter characterWriter = new NTriplesWriter(characters);
		configure(characterWriter);
		assertSame(characters, characterWriter.getWriter());
		action.write(characterWriter);
		assertEquals(expected, characters.toString(), "Writer output");
		assertTrue(characters.flushes > 0);
		assertFalse(characters.closed, "endRDF must leave the caller's writer open");
	}

	@FunctionalInterface
	private interface WriterAction {
		void write(NTriplesWriter writer) throws IOException;
	}

	private static final class RecordingOutputStream extends ByteArrayOutputStream {
		private int flushes;

		private boolean closed;

		@Override
		public void flush() {
			flushes++;
		}

		@Override
		public void close() {
			closed = true;
		}
	}

	private static final class RecordingWriter extends StringWriter {
		private int flushes;

		private boolean closed;

		@Override
		public void flush() {
			flushes++;
		}

		@Override
		public void close() {
			closed = true;
		}
	}

	private static final class ReplacingWriter extends NTriplesWriter {
		private ReplacingWriter(OutputStream output) {
			super(output);
		}

		private ReplacingWriter(Writer output) {
			super(output);
		}

		@Override
		protected void writeValue(Value value) throws IOException {
			super.writeValue(value.equals(SUBJECT) ? VF.createIRI("urn:replacement") : value);
		}
	}
}
